#!/bin/sh
# Generated by FWShift: the rule tables of one Cisco Meraki MX network, put through the Dashboard API (v1).
# Read the report first: what is not written is listed there. Each put replaces the whole table.
# Usage: MERAKI_API_KEY=... NETWORK_ID=N_... [MERAKI_BASE=https://api.meraki.com/api/v1] [DRY_RUN=1] sh this-file
# DRY_RUN=1 only writes the bodies, and needs no key. The backups (before-*.json) end in the fixed default rule of the
# MX: to put a backup back, remove that last rule (comment "Default rule") from its rules first.
set -eu
OUT="${OUT:-meraki-$(date +%Y%m%d%H%M%S)}"
mkdir -p "$OUT"
api() {  # api METHOD PATH [BODY-FILE]
  tries=0
  while :; do
    if [ -n "${3:-}" ]; then
      code=$(curl -sS -o "$OUT/last.json" -D "$OUT/last.hdr" -w '%{http_code}' -X "$1" -H "Authorization: Bearer $MERAKI_API_KEY" \
             -H 'Content-Type: application/json' -H 'Accept: application/json' --data-binary @"$3" "$MERAKI_BASE$2")
    else
      code=$(curl -sS -o "$OUT/last.json" -D "$OUT/last.hdr" -w '%{http_code}' -X "$1" -H "Authorization: Bearer $MERAKI_API_KEY" \
             -H 'Accept: application/json' "$MERAKI_BASE$2")
    fi
    case "$code" in
      2??) cat "$OUT/last.json"; return 0 ;;
      429) tries=$((tries+1)); [ "$tries" -le 5 ] || { echo "rate limited: $2" >&2; return 1; }
           wait=$(sed -n 's/^[Rr]etry-[Aa]fter: *\([0-9]*\).*/\1/p' "$OUT/last.hdr"); sleep "${wait:-2}" ;;
      *) echo "HTTP $code on $1 $2:" >&2; cat "$OUT/last.json" >&2; return 1 ;;
    esac
  done
}
cat > "$OUT/l3FirewallRules.json" <<'FWSHIFT_EOF'
{
 "rules": [
  {
   "comment": "no other web from guests",
   "policy": "deny",
   "protocol": "tcp",
   "srcPort": "Any",
   "srcCidr": "0.0.0.0/0",
   "destPort": "80,443",
   "destCidr": "Any",
   "syslogEnabled": false
  },
  {
   "comment": "no guests elsewhere",
   "policy": "deny",
   "protocol": "any",
   "srcPort": "Any",
   "srcCidr": "0.0.0.0/0",
   "destPort": "Any",
   "destCidr": "Any",
   "syslogEnabled": true
  },
  {
   "comment": "defconf: drop all from WAN not DSTNATed",
   "policy": "deny",
   "protocol": "any",
   "srcPort": "Any",
   "srcCidr": "0.0.0.0/0",
   "destPort": "Any",
   "destCidr": "Any",
   "syslogEnabled": false
  },
  {
   "comment": "the partners reach the web servers of the LAN by HTTPS and nothing else",
   "policy": "allow",
   "protocol": "tcp",
   "srcPort": "Any",
   "srcCidr": "2001:db8:99::/48",
   "destPort": "443",
   "destCidr": "2001:db8:10::/64",
   "syslogEnabled": false
  },
  {
   "comment": "drop everything else not coming from LAN",
   "policy": "deny",
   "protocol": "any",
   "srcPort": "Any",
   "srcCidr": "::/0",
   "destPort": "Any",
   "destCidr": "Any",
   "syslogEnabled": false
  }
 ],
 "syslogDefaultRule": false
}
FWSHIFT_EOF
if [ "${DRY_RUN:-0}" = 1 ]; then echo "DRY_RUN: the bodies are in $OUT"; exit 0; fi
: "${MERAKI_API_KEY:?set MERAKI_API_KEY}"
: "${NETWORK_ID:?set NETWORK_ID}"
MERAKI_BASE="${MERAKI_BASE:-https://api.meraki.com/api/v1}"
api GET "/networks/$NETWORK_ID/appliance/firewall/l3FirewallRules" > "$OUT/before-l3FirewallRules.json"
api PUT "/networks/$NETWORK_ID/appliance/firewall/l3FirewallRules" "$OUT/l3FirewallRules.json" > "$OUT/after-l3FirewallRules.json"
sleep 0.2
echo "done; the tables as they were are in $OUT/before-*.json"
# Not written:
#   defconf: accept in ipsec policy: not converted: ipsec-policy=in,ipsec (traffic of IPsec tunnels)
#   banned scanners: not converted: address list 'scanners', which rules fill while the router runs
#   ssh from the admins: the destination of the rule is in zone DMZ, and the MX names no zone: give the networks behind DMZ with --zone-network
#   web for everyone: the destination of the rule is in zone DMZ, and the MX names no zone: give the networks behind DMZ with --zone-network
#   web for everyone-2: the destination of the rule is in zone DMZ, and the MX names no zone: give the networks behind DMZ with --zone-network
#   ping "echo" only: the destination of the rule is in zone DMZ, and the MX names no zone: give the networks behind DMZ with --zone-network; an ICMP type, or a protocol other than TCP, UDP, ICMP and ICMPv6: the MX has no field for it
#   ping "echo" only-2: the destination of the rule is in zone DMZ, and the MX names no zone: give the networks behind DMZ with --zone-network; an ICMP type, or a protocol other than TCP, UDP, ICMP and ICMPv6: the MX has no field for it
#   nothing but TCP: every service but some: the MX has no negation
#   nothing but TCP-2: every service but some: the MX has no negation
#   rest of the DMZ: not converted: negated destination that does not name the same on both sides of NAT rule 'publish web' (203.0.113.3, 172.16.20.10); not converted: negated destination that does not name the same on both sides of NAT rule 'publish mail' (203.0.113.4, 172.16.20.11)
#   rest of the DMZ-2: not converted: negated destination that does not name the same on both sides of NAT rule 'publish web' (203.0.113.3, 172.16.20.10); not converted: negated destination that does not name the same on both sides of NAT rule 'publish mail' (203.0.113.4, 172.16.20.11); every service but some: the MX has 
#   rest of the DMZ-3: not converted: negated destination that does not name the same on both sides of NAT rule 'publish web' (203.0.113.3, 172.16.20.10); not converted: negated destination that does not name the same on both sides of NAT rule 'publish mail' (203.0.113.4, 172.16.20.11); port 0, which the MX does not take
#   LAN to the package mirrors: the source of the rule is in zone LAN, and the MX names no zone: give the networks behind LAN with --zone-network; 'mirrors' holds members only its platform knows
#   guest DNS, either port: the source of the rule is in zone GUEST, and the MX names no zone: give the networks behind GUEST with --zone-network; the destination of the rule is in zone WAN, and the MX names no zone: give the networks behind WAN with --zone-network
#   guest DNS, either port-2: the source of the rule is in zone GUEST, and the MX names no zone: give the networks behind GUEST with --zone-network; the destination of the rule is in zone WAN, and the MX names no zone: give the networks behind WAN with --zone-network
#   guests to the internet: the source of the rule is in zone GUEST, and the MX names no zone: give the networks behind GUEST with --zone-network; the destination of the rule is in zone WAN, and the MX names no zone: give the networks behind WAN with --zone-network
#   office hours for staff: schedule 'time=8h-18h,mon,tue,wed,thu,fri' is not converted; the rule would apply at all times; schedule time=8h-18h,mon,tue,wed,thu,fri is not converted; the source of the rule is in zone LAN, and the MX names no zone: give the networks behind LAN with --zone-network; the destination of the rule is
#   defconf: drop all from WAN not DSTNATed (allows publish web): the source of the rule is in zone WAN, and the MX names no zone: give the networks behind WAN with --zone-network
#   defconf: drop all from WAN not DSTNATed (allows publish mail): the source of the rule is in zone WAN, and the MX names no zone: give the networks behind WAN with --zone-network
#   ICMPv6 echo: an ICMP type, or a protocol other than TCP, UDP, ICMP and ICMPv6: the MX has no field for it
